def solve(n):
    seq = [0]*(2*n)
    def bt(v):
        if v == 0:
            return True
        # place largest first
        for i in range(2*n - v - 1):
            if seq[i]==0 and seq[i+v+1]==0:
                seq[i]=v; seq[i+v+1]=v
                if bt(v-1): return True
                seq[i]=0; seq[i+v+1]=0
        return False
    if bt(n):
        return seq
    return None

print(solve(12))
